import {allergens,days,meals,foods,seeds,eligible,shopping,totals,planAuto,parseText,quickSuggestions} from './core.js';
const $=s=>document.querySelector(s);const euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16)).join("-");const icons={plan:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M3 10h18M7 3v4M17 3v4M7 14h3m4 0h3M7 17h3"/>',recipes:'<path d="M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4zM14 7a3 3 0 0 1 3-3h4v14h-3a4 4 0 0 0-4 3"/>',shop:'<path d="M2 3h3l3 13h11l3-9H6M9 21h.01M18 21h.01"/>',pantry:'<path d="M4 4h16v17H4zM4 10h16M8 7h8M8 14h8M8 17h8"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="16" cy="17" r="3" fill="white"/>'};const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[n]}</svg>`;
function monday(date){const d=new Date(date);d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return d.toISOString().slice(0,10)}
const defaultState=()=>({version:1,week:monday(new Date()),settings:{days:[0,1,2,3,4],meals:['Frühstück','Mittagessen','Abendessen'],persons:2,budget:65,maxTime:40,diet:'Vegetarisch',allergens:[],excludes:'',goals:[],minProtein:25,maxCarbs:30,maxKcal:450,minKcal:650,glutenfree:false,lactosefree:false,preferFav:true},recipes:structuredClone(seeds),plans:{},pantry:{},prices:{},priceDates:{},checked:{},manual:[],overrides:{}});
let state;try{state=JSON.parse(localStorage.getItem('tisch-tag-v1'))||defaultState();}catch{state=defaultState();}let page='plan',day=0,query='',favOnly=false;let recipeFilter='all';let draft=null;let importUrl='';let slotTarget=null;let notice='';let saveFailed=false;
function save(){try{localStorage.setItem('tisch-tag-v1',JSON.stringify(state));saveFailed=false;}catch{saveFailed=true;toast('Speicher voll oder gesperrt. Bitte Daten exportieren.');}}
if(!state.quickCatalogV2){if(!state.recipes.some(r=>r.id==='linsen-schnell'))state.recipes.push(structuredClone(seeds.find(r=>r.id==='linsen-schnell')));state.quickCatalogV2=true;save();}
if(!state.plans[state.week]){state.plans[state.week]={'0-Frühstück':{recipe:'porridge',portions:2},'0-Mittagessen':{recipe:'bowl',portions:2},'0-Abendessen':{recipe:'curry',portions:2},'1-Abendessen':{recipe:'linsen',portions:2},'2-Abendessen':{recipe:'pasta',portions:2}};save();}
const plan=()=>state.plans[state.week]||{};const rows=()=>shopping(plan(),state.recipes,state.pantry,state.prices);const metrics=()=>totals(rows().map(r=>{const need=state.overrides[state.week+'|'+r.key]??r.need;return {...r,cost:r.pack?Math.ceil(need/r.pack)*r.price:0};}));const recipe=id=>state.recipes.find(r=>r.id===id);const img=r=>{const urls={curry:'photo-1603894584373-5ac82b2ae398',pasta:'photo-1473093295043-cdd812d0e601',bowl:'photo-1512621776951-a57141f2eefd',lentils:'photo-1547592180-85f173990554',porridge:'photo-1517673400267-0251440c45dc',eggs:'photo-1525351484163-7529414344d8',salad:'photo-1512621776951-a57141f2eefd'};return `https://images.unsplash.com/${urls[r.image]||urls.salad}?auto=format&fit=crop&w=700&q=85`};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function modal(title,body){$('#dialog').innerHTML=`<div class="modal-header"><h2>${esc(title)}</h2><button class="icon-btn" id="close-dialog" aria-label="Dialog schließen">✕</button></div><div class="modal-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();$('#close-dialog').onclick=()=>$('#dialog').close();}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function weekLabel(){const a=new Date(state.week+'T12:00:00');const b=new Date(a);b.setDate(b.getDate()+6);return `${a.toLocaleDateString('de-DE',{day:'numeric',month:'short'})} – ${b.toLocaleDateString('de-DE',{day:'numeric',month:'short',year:'numeric'})}`;}
icons.quick='<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>';
const titleMap={quick:'Schnelles Essen',plan:'Wochenplan',recipes:'Meine Rezepte',shop:'Einkaufsliste',pantry:'Meine Vorräte',settings:'Einstellungen'};
function shell(content){$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-icon">♧</span>Tisch & Tag<span style="font-size:12px;color:#9ba98c">®</span></div><nav class="nav" aria-label="Hauptnavigation">${Object.entries(titleMap).map(([k,v])=>`<button data-nav="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${icon(k)}${v.replace('Meine ','')}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="small-note"><b>Ein guter Plan. Weniger Reste.</b><span class="tiny muted">Bewusst einkaufen, entspannt kochen und jeden Tag genießen.</span><div style="margin-top:12px;color:#748b5b">✳ &nbsp; Für dich & deinen Alltag</div></div><div class="profile"><span class="avatar">M</span><div><b style="font-size:12px">Mein Küchenalltag</b><div class="tiny muted" style="margin-top:4px">Persönlicher Bereich</div></div></div></div></aside><main class="main"><header class="topbar"><span>Mein Küchenalltag &nbsp; / &nbsp; <b style="color:#56634f;font-weight:500">${titleMap[page]}</b></span><div class="mobile-brand">♧ Tisch & Tag</div><div class="right"><span class="saved"><i class="dot"></i>${saveFailed?'Speicher prüfen':'Lokal gespeichert'}</span><span class="avatar" style="width:29px;height:29px;font-size:11px">M</span></div></header>${content}<footer class="page-footer">Mit Liebe geplant. Mit Genuss gekocht. &nbsp; ✳ &nbsp; Tisch & Tag<br><span style="font-size:9px">Beispielpreise vom 04.11.2026 · Keine Live-Angebote · Daten bleiben auf diesem Gerät</span></footer></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;render();});}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="row">${actions}</div></div>`;}
function portionCost(r){return r.ingredients.reduce((sum,i)=>{const f=foods[i.food];return sum+(f?i.qty/f.pack*(state.prices[i.food]??f.price):0)},0)/r.servings;}
function card(r,key=null,p=null){return `<article class="meal-card"><div class="meal-image"><img src="${img(r)}" alt="Serviervorschlag" loading="lazy"><span class="pill">${esc(r.diet)}</span><button class="heart" data-fav="${r.id}" aria-label="${r.favorite?'Favorit entfernen':'Als Favorit speichern'}">${r.favorite?'♥':'♡'}</button></div><div class="meal-body"><button class="recipe-link" data-open="${r.id}"><h3>${esc(r.title)}</h3></button><div class="meta"><span>◷ ${r.time??'?'} Min.</span><span>≈ ${euro(portionCost(r))}</span><span>${r.kcal??'?'} kcal</span></div><div class="meal-footer"><span>${p?`${p.portions} Portionen${p.leftover?' · Reste':''}${p.cooked?' · gekocht':''}`:esc(r.tags.join(' · '))}</span><span>${key?`<button class="icon-btn" data-lock="${key}" aria-label="Gericht ${p.locked?'entsperren':'fixieren'}">${p.locked?'▣':'⌑'}</button><button class="icon-btn" data-swap="${key}" aria-label="Gericht austauschen">⇄</button><button class="icon-btn" data-slot="${key}" aria-label="Mahlzeit bearbeiten">⋯</button>`:`<button class="icon-btn" data-add-plan="${r.id}" aria-label="In Wochenplan übernehmen">＋</button>`}</span></div></div></article>`;}
function bindCards(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecipe(b.dataset.open));document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{recipe(b.dataset.fav).favorite=!recipe(b.dataset.fav).favorite;save();render();});document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>{plan()[b.dataset.lock].locked=!plan()[b.dataset.lock].locked;save();render();});document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>pickRecipe(b.dataset.swap));document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>slotEditor(b.dataset.slot));document.querySelectorAll('[data-add-plan]').forEach(b=>b.onclick=()=>addToPlan(b.dataset.addPlan));}
function renderPlan(){const t=metrics(),ps=Object.values(plan()).reduce((s,p)=>s+p.portions,0),n=Object.keys(plan()).length;const date=new Date(state.week+'T12:00:00');date.setDate(date.getDate()+day);const selected=state.settings.days.includes(day);const actual=meals.filter(m=>state.settings.meals.includes(m));const content=heading('WENIGER PLANEN. MEHR GENIESSEN.','Deine Woche, gut geplant.','Gutes Essen beginnt mit einem entspannten Plan.',`<button class="secondary" id="quick-shortcut">ϟ Schnelles Essen</button><button class="secondary" id="plan-settings">⚙ &nbsp; Plan anpassen</button><button class="primary" id="generate">✧ &nbsp; Plan erstellen</button>`)+`<div class="stats"><div class="stat"><div class="stat-label">Dein Einkaufsbudget <span>◉</span></div><strong>${euro(t.buy)}</strong><small>von ${euro(state.settings.budget)}</small><div class="bar"><span style="width:${Math.min(100,t.buy/state.settings.budget*100)}%"></span></div><div class="stat-foot">${euro(Math.abs(state.settings.budget-t.buy))} ${state.settings.budget>=t.buy?'übrig für deine Woche':'über Budget'}${t.unknown?' · Kosten unvollständig':''}</div></div><div class="stat"><div class="stat-label">Geplante Mahlzeiten <span>♧</span></div><strong>${n}</strong><small>von ${state.settings.days.length*state.settings.meals.length}</small><div class="stat-foot muted" style="margin-top:17px">Für ${state.settings.persons} Personen · ${state.settings.days.length} ausgewählte Tage</div></div><div class="stat"><div class="stat-label">Verbrauchswert pro Portion <span>↗</span></div><strong>${euro(ps?t.used/ps:0)}</strong><div class="stat-foot muted" style="margin-top:17px">${euro(t.used)} Zutatenwert · ganze Packungen im Budget</div></div></div>${notice?`<div class="warning">${esc(notice)}</div>`:''}${t.buy>state.settings.budget?`<div class="warning">Dein Plan überschreitet das Budget um ${euro(t.buy-state.settings.budget)}. Tausche teure Gerichte aus, berücksichtige Vorräte oder passe das Budget an. Deine Einstellungen bleiben erhalten.</div>`:''}<div class="week-toolbar"><div><div class="week-title">Dein Wochenplan <small> &nbsp; ${weekLabel()}</small></div><div class="chips" style="margin-top:12px"><span class="chip green">♧ ${esc(state.settings.diet)}</span><span class="chip">◷ Bis ${state.settings.maxTime} Min.</span><span class="chip">♙ ${state.settings.persons} Personen</span>${state.settings.allergens.length?`<span class="chip">${state.settings.allergens.length} Ausschlüsse</span>`:''}</div></div><div class="week-controls"><button id="prev-week" aria-label="Vorherige Woche">‹</button><span>Diese Woche</span><button id="next-week" aria-label="Nächste Woche">›</button></div></div><section class="planning"><div class="daytabs" role="tablist" aria-label="Wochentag">${days.map((d,i)=>{const date=new Date(state.week+'T12:00:00');date.setDate(date.getDate()+i);return `<button role="tab" aria-selected="${i===day}" class="${i===day?'active ':''}${state.settings.days.includes(i)?'selected':''}" data-day="${i}">${d.slice(0,2)}<span>${date.getDate()}</span></button>`;}).join('')}</div><div class="day-content"><div class="day-heading"><h2>${days[day]}, ${date.toLocaleDateString('de-DE',{day:'numeric',month:'long'})}</h2><span class="muted">${selected?'Ein guter Tag für gutes Essen.':'Dieser Tag ist nicht zur Planung ausgewählt.'}</span></div><div class="cards">${selected?actual.map(m=>{const key=day+'-'+m,p=plan()[key],r=p&&recipe(p.recipe);return `<div><div class="meal-label">${m}<span>${m==='Frühstück'?'☀':m==='Mittagessen'?'◔':m==='Snack'?'✧':'☾'}</span></div>${r?card(r,key,p):`<div class="empty-card"><span style="font-size:24px">＋</span><span>Platz für etwas Leckeres</span><button data-pick="${key}">Gericht auswählen</button></div>`}</div>`}).join(''):`<div class="empty-card" style="grid-column:1/-1"><span>Heute bleibt die Küche frei.</span><button id="enable-day">Tag einplanen</button></div>`}</div></div></section><div class="below"><div class="tip"><div class="tip-icon">♧</div><div><b>Einmal kochen, zweimal genießen.</b><p>Über das Menü einer Mahlzeit kannst du zusätzliche Portionen kochen und für einen anderen Tag als Reste einplanen.</p></div></div><div class="shopping-promo"><div><b>Alles auf deiner Einkaufsliste</b><p>${rows().filter(x=>x.need>0).length} Zutaten · nach Bereichen sortiert</p></div><button class="secondary" id="go-shop">Zur Liste &nbsp; ↗</button></div></div>`;
shell(content);$('#quick-shortcut').onclick=()=>{page='quick';render();};$('#generate').onclick=()=>{const r=planAuto(state);state.plans[state.week]=r.plan;notice=r.misses.length?`Keine passenden geprüften Rezepte für: ${r.misses.join(', ')}. Bitte Rezeptbestand erweitern oder Bedingungen bewusst anpassen.`:'Plan erstellt. Fixierte passende Gerichte wurden beibehalten.';save();render();};$('#plan-settings').onclick=()=>{page='settings';render();};$('#go-shop').onclick=()=>{page='shop';render();};for(const [id,delta]of [['prev-week',-7],['next-week',7]])$('#'+id).onclick=()=>{const d=new Date(state.week+'T12:00:00');d.setDate(d.getDate()+delta);state.week=monday(d);state.plans[state.week]??={};notice='';save();render();};document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=+b.dataset.day;render();});document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>pickRecipe(b.dataset.pick));if($('#enable-day'))$('#enable-day').onclick=()=>{state.settings.days.push(day);save();render();};bindCards();}
function pickRecipe(key){const meal=key.split('-')[1];const options=state.recipes.filter(r=>eligible(r,state.settings,meal));modal('Gericht auswählen',`<p class="muted">Nur Rezepte, die zu deinen verbindlichen Einstellungen passen.</p>${options.length?options.map(r=>`<div class="list-row"><div class="grow"><b>${esc(r.title)}</b><p>${r.time} Min. · ${euro(portionCost(r))} / Portion · ${r.kcal??'?'} kcal</p></div><button class="secondary" data-choose="${r.id}">Auswählen</button></div>`).join(''):'<div class="warning">Keine passenden geprüften Rezepte. Ergänze Rezepte oder passe deine Einstellungen bewusst an.</div>'}`);document.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>{const prev=plan()[key];if(prev?.leftover||Object.values(plan()).some(p=>p.leftover===key)){toast('Reste-Verknüpfung zuerst über Mahlzeit entfernen.');return;}plan()[key]={recipe:b.dataset.choose,portions:prev?.portions||state.settings.persons};save();$('#dialog').close();render();});}
function addToPlan(id){modal('Zum Wochenplan hinzufügen',`<label>Tag<select id="add-day">${state.settings.days.map(i=>`<option value="${i}">${days[i]}</option>`).join('')}</select></label><label style="margin-top:15px">Mahlzeit<select id="add-meal">${state.settings.meals.map(m=>`<option>${m}</option>`).join('')}</select></label><div class="form-actions"><button class="primary" id="confirm-add">Einplanen</button></div>`);$('#confirm-add').onclick=()=>{const m=$('#add-meal').value,r=recipe(id),key=$('#add-day').value+'-'+m;if(!eligible(r,state.settings,m)){toast('Rezept erfüllt deine Ernährungs-, Zeit- oder Allergenregeln nicht.');return;}if(plan()[key]){toast('Diese Mahlzeit ist belegt. Bitte zuerst entfernen oder dort austauschen.');return;}plan()[key]={recipe:id,portions:state.settings.persons};save();$('#dialog').close();page='plan';day=+key.split('-')[0];render();};}
function slotEditor(key){const p=plan()[key];const r=recipe(p.recipe);const source=p.leftover?plan()[p.leftover]:null;const targets=state.settings.days.flatMap(d=>state.settings.meals.map(m=>({key:d+'-'+m,label:days[d]+' · '+m}))).filter(t=>t.key!==key&&!plan()[t.key]);const linked=Object.entries(plan()).filter(([,v])=>v.leftover===key);modal('Mahlzeit bearbeiten',`<h3>${esc(r.title)}</h3>${p.leftover?'<div class="success">Restemahlzeit: Zutaten werden nur bei der ursprünglichen Mahlzeit berechnet.</div>':''}<label>Portionen ${p.leftover?'zum Essen':'zum Essen (ohne zusätzliche Reste)'}<input type="number" min="1" max="30" step="1" id="portions" value="${p.leftover?p.portions:p.portions-linked.reduce((s,[,v])=>s+v.portions,0)}" ${p.cooked?'disabled':''}></label>${!p.leftover&&!p.cooked&&targets.length?`<div class="form-grid" style="margin-top:18px"><label>Zusätzlich als Reste für<select id="rest-target"><option value="">Keine zusätzlichen Reste</option>${targets.filter(t=>t.key>key).map(t=>`<option value="${t.key}">${t.label}</option>`).join('')}</select></label><label>Zusätzliche Portionen<input type="number" id="rest-portions" value="2" min="1" max="30"></label></div>`:''}<div class="source-note">${linked.length?`Bereits verknüpfte Reste: ${linked.map(([k,v])=>days[+k.split('-')[0]]+' '+k.split('-')[1]+': '+v.portions+' Portionen').join(', ')}.`:''} Vorräte werden erst mit „Gekocht“ abgezogen. Warme Speisen rasch abkühlen und passend kühlen; bei Unsicherheit frisch zubereiten.</div><div class="form-grid" style="margin-top:18px"><label>Verschieben nach<select id="move-target"><option value="">Am bisherigen Platz lassen</option>${targets.map(t=>`<option value="${t.key}">${t.label}</option>`).join('')}</select></label></div><div class="form-actions"><button class="secondary" id="delete-slot">Entfernen</button>${!p.leftover&&!p.cooked?'<button class="secondary" id="cooked">✓ Gekocht</button>':''}<button class="primary" id="save-slot">Speichern</button></div>`);
$('#save-slot').onclick=()=>{if(p.cooked){$('#dialog').close();return;}const portions=+$('#portions').value;if(!Number.isInteger(portions)||portions<1||portions>30){toast('Bitte 1–30 ganze Portionen eingeben.');return;}if(p.leftover){const delta=portions-p.portions;if(source?.cooked&&delta){toast('Die Quelle wurde bereits gekocht; Portionen sind fest.');return;}if(source)source.portions+=delta;p.portions=portions;}else p.portions=portions+linked.reduce((s,[,v])=>s+v.portions,0);const rest=$('#rest-target')?.value;if(rest){const rp=+$('#rest-portions').value;if(!Number.isInteger(rp)||rp<1||rp>30){toast('Restemenge muss 1–30 Portionen sein.');return;}plan()[rest]={recipe:p.recipe,portions:rp,leftover:key};p.portions+=rp;}const move=$('#move-target').value;if(move){if(rest===move){toast('Reste und Ursprungsgericht brauchen verschiedene Plätze.');return;}if(!eligible(r,state.settings,move.split('-')[1])){toast('Rezept passt nicht zur Zielmahlzeit.');return;}plan()[move]=p;delete plan()[key];for(const v of Object.values(plan()))if(v.leftover===key)v.leftover=move;}save();$('#dialog').close();render();};
$('#delete-slot').onclick=()=>{if(p.leftover&&source&&!source.cooked)source.portions-=p.portions;for(const[k]of linked)delete plan()[k];delete plan()[key];save();$('#dialog').close();render();};if($('#cooked'))$('#cooked').onclick=()=>{for(const i of r.ingredients){const amount=i.qty*p.portions/r.servings;state.pantry[i.food]=Math.max(0,(state.pantry[i.food]||0)-amount);}p.cooked=true;save();$('#dialog').close();render();toast('Gekocht markiert. Verwendete Vorräte wurden abgezogen.');};}
function openRecipe(id,servings=null,cooking=false){const r=recipe(id);let portions=servings||r.servings;const known=r.ingredients.flatMap(i=>foods[i.food]?.allergens||[]);modal(r.title,cooking?`<div class="cooking">${r.steps.map((s,i)=>`<label><input type="checkbox"><span><b>${i+1}.</b> ${esc(s)}</span></label>`).join('')}</div><button class="secondary" id="back-recipe">Zur Rezeptansicht</button>`:`<img src="${img(r)}" alt="Serviervorschlag – kein Foto der genauen Rezeptur"><div class="chips"><span class="chip green">${esc(r.diet)}</span><span class="chip">Vorbereitung ${r.prep??'?'} Min.</span><span class="chip">Gesamt ${r.time??'?'} Min.</span><span class="chip">Kochzeit ${r.time&&r.prep?Math.max(0,r.time-r.prep):'?'} Min.</span></div><div class="row" style="margin:20px 0;justify-content:space-between"><label>Portionen<input style="width:90px" type="number" id="recipe-portions" min="1" max="30" value="${portions}"></label><button class="primary" id="cook-mode">Kochmodus starten &nbsp; →</button></div><div class="success">Pro Portion (Schätzung): ${r.kcal??'?'} kcal · ${r.protein??'?'} g Protein · ${r.carbs??'?'} g Kohlenhydrate · ${r.fat??'?'} g Fett · ≈ ${euro(portionCost(r))}</div><h3 style="margin-top:23px">Zutaten</h3><ul class="ingredients">${r.ingredients.map(i=>`<li><b>${i.qty?+(i.qty*portions/r.servings).toFixed(1):'Menge ungeklärt'} ${esc(foods[i.food]?.unit||i.unit||'')}</b> &nbsp; ${esc(foods[i.food]?.name||i.food)}</li>`).join('')}</ul><h3>Zubereitung</h3><ol class="steps">${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="warning">Allergene: ${known.length?[...new Set(known)].map(esc).join(', '):r.verified?'Keine der 14 Gruppen in den angegebenen Grundzutaten':'Ungeklärt'}. ${!r.verified?'Zusammensetzung noch nicht vollständig geprüft. ':''}Produktetiketten und mögliche Spuren prüfen. Keine Zusicherung zu Kreuzkontamination.</div><div class="source-note">${esc(r.source)}${r.url?` · <a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Original öffnen</a>`:''}<br>Bilder: Unsplash · Illustrative Serviervorschläge. Beispielpreise, keine aktuellen Supermarktangebote.</div><div class="form-grid" style="margin-top:20px"><label>Persönliche Notizen<textarea id="recipe-note">${esc(r.note||'')}</textarea></label><label>Bewertung<select id="recipe-rating">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${r.rating===n?'selected':''}>${n?n+' von 5 Sternen':'Noch nicht bewertet'}</option>`).join('')}</select></label></div><div class="form-actions"><button class="secondary" id="edit-recipe">Bearbeiten</button><button class="secondary" id="delete-recipe">Löschen</button><button class="primary" id="save-note">Notiz speichern</button></div>`);
if(cooking){$('#back-recipe').onclick=()=>openRecipe(id,portions);return;}$('#recipe-portions').onchange=e=>{const n=+e.target.value;if(n>=1&&n<=30)openRecipe(id,n);};$('#cook-mode').onclick=()=>openRecipe(id,portions,true);$('#edit-recipe').onclick=()=>{draft=structuredClone(r);editDraft();};$('#delete-recipe').onclick=()=>{const inUse=Object.values(state.plans).some(p=>Object.values(p).some(s=>s.recipe===id));if(inUse){toast('Rezept ist noch in einem Wochenplan. Entferne zuerst diese Mahlzeiten.');return;}modal('Rezept löschen?',`<p>„${esc(r.title)}“ dauerhaft aus der Sammlung löschen?</p><div class="form-actions"><button class="secondary" id="cancel-delete">Abbrechen</button><button class="primary" id="confirm-delete">Rezept löschen</button></div>`);$('#cancel-delete').onclick=()=>openRecipe(id);$('#confirm-delete').onclick=()=>{state.recipes=state.recipes.filter(x=>x.id!==id);save();$('#dialog').close();render();};};$('#save-note').onclick=()=>{r.note=$('#recipe-note').value;r.rating=+$('#recipe-rating').value;save();toast('Notiz und Bewertung gespeichert.');};}
function renderRecipes(){const recipes=state.recipes.filter(r=>(!favOnly||r.favorite)&&(recipeFilter==='all'||r.diet===recipeFilter)&&(r.title+' '+r.ingredients.map(i=>foods[i.food]?.name||i.food).join(' ')+' '+r.tags.join(' ')).toLowerCase().includes(query.toLowerCase()));shell(heading('DEINE KÜCHE. DEINE LIEBLINGSGERICHTE.','Gute Ideen für jeden Tag.','Entdecken, sammeln und immer wieder genießen.',`<button class="secondary" id="import-recipe">↗ &nbsp; Rezept importieren</button><button class="primary" id="new-recipe">＋ &nbsp; Eigenes Rezept</button>`)+`<div class="searchbar"><input aria-label="Rezepte nach Titel, Zutat oder Tag suchen" placeholder="⌕   Rezept, Zutat oder Tag suchen …" id="search" value="${esc(query)}"><select id="recipe-filter" aria-label="Ernährungsform" style="width:180px">${['all','Vegan','Vegetarisch','Pescetarisch','Mischkost','Ungeprüft'].map(v=>`<option value="${v}" ${recipeFilter===v?'selected':''}>${v==='all'?'Alle Ernährungsformen':v}</option>`).join('')}</select><button class="secondary" id="favorites">${favOnly?'♥ Nur Favoriten':'♡ Favoriten'}</button></div><div class="recipe-grid">${recipes.map(r=>card(r)).join('')}</div>${!recipes.length?'<div class="section muted">Keine Rezepte für diese Suche. Probiere eine andere Zutat.</div>':''}<p class="source-note">Eigene Beispielrezepturen · Nährwerte und Preise sind Schätzungen. Importierte Rezepte vor Verwendung prüfen.</p>`);$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};$('#recipe-filter').onchange=e=>{recipeFilter=e.target.value;render();};$('#favorites').onclick=()=>{favOnly=!favOnly;render();};$('#new-recipe').onclick=()=>{draft=parseText('Mein neues Rezept\nZutaten\n100 g Reis\nZubereitung\nZubereitung hier beschreiben.');draft.tags=['Eigene Rezepte'];draft.source='Eigene Rezeptur';editDraft();};$('#import-recipe').onclick=importDialog;bindCards();}
function importDialog(){modal('Rezept importieren',`<p class="muted">Aus deinem Lieblingsbeitrag wird ein Rezept für deine Sammlung.</p><label>Instagram-, TikTok- oder Website-Link<input type="url" id="import-url" placeholder="https://…" value="${esc(importUrl)}"></label><div class="form-actions"><button class="secondary" id="fetch-recipe">Link auslesen</button></div><p id="import-status" role="status" class="warning">Website-Import benötigt den optionalen Importserver. Geschützte Social-Media-Beiträge können nicht automatisch gelesen werden. Füge alternativ die Caption hier ein.</p><label>Rezepttext oder Caption<textarea id="import-text" rows="10" placeholder="Titel des Rezepts&#10;Zutaten&#10;200 g Tomaten&#10;Zubereitung&#10;1. Tomaten schneiden …"></textarea></label><p class="source-note">Erste Zeile = Titel. Zutatenzeilen z. B. „200 g Tomaten“. Mit „Zubereitung“ beginnt die Anleitung. Fehlende Mengen bleiben ungeklärt.</p><div class="form-actions"><button class="primary" id="parse-text">Rezeptentwurf prüfen</button></div>`);$('#parse-text').onclick=()=>{const text=$('#import-text').value.trim();if(!text){toast('Bitte zuerst einen Rezepttext einfügen.');return;}importUrl=$('#import-url').value;if(importUrl&&!safeUrl(importUrl)){toast('Bitte einen öffentlichen HTTPS-Link eingeben.');return;}draft=parseText(text);draft.url=importUrl;draft.source=importUrl?'Import · '+new URL(importUrl).hostname:'Textimport';editDraft();};$('#fetch-recipe').onclick=async()=>{const url=$('#import-url').value;if(!safeUrl(url)){toast('Bitte einen gültigen öffentlichen HTTPS-Link eingeben.');return;}$('#fetch-recipe').disabled=true;$('#import-status').textContent='Rezept wird abgerufen …';try{const endpoint=localStorage.getItem('tisch-import-endpoint')||'/api/import';const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url}),signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error(response.status===404||response.status===405?'Importserver ist hier noch nicht eingerichtet.':(await response.json()).error||'Quelle nicht lesbar.');const data=await response.json();if(!data.text)throw new Error('Keine strukturierten Rezeptdaten gefunden.');draft=parseText(data.text);draft.url=url;draft.source='Website-Import · '+new URL(url).hostname;editDraft();}catch(e){$('#import-status').textContent=e.message+' Bitte Caption oder Rezepttext unten einfügen. Es wurde kein Rezept erfunden.';$('#import-text').focus();}finally{if($('#fetch-recipe'))$('#fetch-recipe').disabled=false;}};}
function safeUrl(s){try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password&&!/^(localhost|127\.|10\.|192\.168\.|169\.254\.|\[|0\.)/i.test(u.hostname)&&u.hostname.includes('.');}catch{return false;}}
function editDraft(){const text=draft.ingredients.map(i=>`${i.qty||'?'} ${foods[i.food]?.unit||i.unit||'?'} ${foods[i.food]?.name||i.food}`).join('\n');modal('Rezeptentwurf prüfen & bearbeiten',`<form id="draft-form"><div class="warning">${draft.verified?'Bestehende Angaben prüfen.':'Allergenangaben und fehlende Mengen sind ungeprüft. Dieser Entwurf wird erst nach deiner Bestätigung gespeichert.'}</div><label>Titel<input name="title" required value="${esc(draft.title)}"></label><div class="form-grid" style="margin-top:16px"><label>Portionen<input name="servings" type="number" min="1" max="30" required value="${draft.servings}"></label><label>Gesamtzeit in Minuten (leer = unbekannt)<input name="time" type="number" min="1" value="${draft.time||''}"></label><label>Ernährungsform<select name="diet">${['Ungeprüft','Vegan','Vegetarisch','Pescetarisch','Mischkost'].map(d=>`<option ${draft.diet===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Tags / Sammlungen (kommagetrennt)<input name="tags" value="${esc(draft.tags.join(', '))}"></label></div><label style="margin-top:16px">Zutaten · eine je Zeile, z. B. 200 g Tomaten<textarea name="ingredients" required rows="6">${esc(text)}</textarea></label><label style="margin-top:16px">Zubereitung · ein Schritt je Zeile<textarea name="steps" rows="5" required>${esc(draft.steps.join('\n'))}</textarea></label><div class="checks" style="margin:15px 0">${meals.map(m=>`<label class="check"><input name="meal" type="checkbox" value="${m}" ${draft.meal.includes(m)?'checked':''}>${m}</label>`).join('')}</div><div class="form-grid">${[['kcal','Kalorien pro Portion'],['protein','Protein g pro Portion'],['carbs','Kohlenhydrate g pro Portion'],['fat','Fett g pro Portion']].map(([k,l])=>`<label>${l} (optional)<input name="${k}" type="number" min="0" value="${draft[k]??''}"></label>`).join('')}</div><p class="source-note">Nur Zutaten aus dem eingebauten Katalog können hier mit geprüfter Allergenstruktur und Packungspreisen verwendet werden. Andere Zutaten bleiben ungeprüft und werden nicht automatisch bei Allergenausschlüssen eingeplant.</p><label class="check"><input type="checkbox" name="verified" ${draft.verified?'checked':''}>Ich habe die Ernährungsform und alle Zutaten geprüft.</label><div id="draft-errors" role="alert"></div><div class="form-actions"><button class="primary" type="submit">Bestätigen & Rezept speichern</button></div></form>`);$('#draft-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const p=parseText(f.get('title')+'\nZutaten\n'+f.get('ingredients')+'\nZubereitung\n'+f.get('steps'));if(!p.ingredients.length||!p.steps.length||!f.getAll('meal').length){$('#draft-errors').textContent='Bitte Zutaten, Schritte und mindestens eine Mahlzeit angeben.';return;}if(p.ingredients.some(i=>!i.qty)){ $('#draft-errors').innerHTML='<div class="warning">Fehlende oder unlesbare Mengen bitte korrigieren. Beispiel: „200 g Tomaten“.</div>';return;}const duplicate=state.recipes.find(r=>r.id!==draft.id&&r.title.trim().toLowerCase()===f.get('title').trim().toLowerCase());if(duplicate){$('#draft-errors').innerHTML='<div class="warning">Ein Rezept mit diesem Titel existiert bereits. Bitte Titel anpassen oder vorhandenes Rezept bearbeiten.</div>';return;}const r={...draft,title:f.get('title').trim(),servings:+f.get('servings'),time:f.get('time')?+f.get('time'):null,diet:f.get('diet'),tags:f.get('tags').split(',').map(s=>s.trim()).filter(Boolean),meal:f.getAll('meal'),ingredients:p.ingredients,steps:p.steps,verified:f.has('verified')&&p.ingredients.every(i=>foods[i.food])};for(const k of ['kcal','protein','carbs','fat'])r[k]=f.get(k)===''?null:+f.get(k);const idx=state.recipes.findIndex(x=>x.id===r.id);if(idx>=0){const invalid=Object.values(state.plans).some(pl=>Object.entries(pl).some(([key,slot])=>slot.recipe===r.id&&!eligible(r,state.settings,key.split('-')[1])));if(invalid){$('#draft-errors').innerHTML='<div class="warning">Änderungen widersprechen den Regeln eines eingeplanten Gerichts. Entferne das Rezept zuerst aus dem Plan.</div>';return;}state.recipes[idx]=r;}else state.recipes.push(r);save();$('#dialog').close();page='recipes';render();toast('Rezept in deiner Sammlung gespeichert.');};}
function renderShop(){const list=rows().map(r=>({...r,need:state.overrides[state.week+'|'+r.key]??r.need})).map(r=>({...r,packs:r.pack?Math.ceil(r.need/r.pack):null,cost:r.pack?Math.ceil(r.need/r.pack)*r.price:0}));const t=totals(list);const groups=[...new Set(list.map(x=>x.group))];shell(heading('GUT SORTIERT. SCHNELL ERLEDIGT.','Alles für deine Woche.','Zusammengefasst aus deinem Plan, abzüglich deiner Vorräte.',`<button class="secondary" id="print">Drucken</button><button class="secondary" id="export-list">↓ Als Text</button><button class="primary" id="manual-add">＋ Artikel</button>`)+`<div class="section"><div class="row" style="justify-content:space-between"><div><div class="muted tiny">GESCHÄTZTE EINKAUFSAUSGABEN</div><h2 style="margin:9px 0">${euro(t.buy)} <span class="muted" style="font-size:13px">/ ${euro(state.settings.budget)} Budget</span></h2></div><span class="badge">${weekLabel()}</span></div><div class="source-note">Volle Packungen · Beispielpreise vom 04.11.2026, außer manuell korrigiert. Änderungen der Einkaufsmenge gelten für diese Woche. Unbekannte Preise sind nicht im Gesamtbetrag enthalten.</div>${t.unknown?'<div class="warning">Für eigene Zutaten fehlen Packungsgrößen und Preise. Die Summe ist unvollständig.</div>':''}</div><div class="section">${groups.length?groups.map(g=>`<h3 class="group-title">${g}</h3>${list.filter(x=>x.group===g).map(r=>`<div class="list-row ${state.checked[state.week+'|'+r.key]?'done':''}"><input type="checkbox" data-check="${esc(r.key)}" aria-label="${esc(r.name)} gekauft" ${state.checked[state.week+'|'+r.key]?'checked':''}><div class="grow"><b class="item-name">${esc(r.name)}</b><p>Benötigt: ${+r.qty.toFixed(1)} ${esc(r.unit)} · Vorrat: ${state.pantry[r.food]||0} ${esc(r.unit)}</p><p>Für ${r.dishes.map(esc).join(', ')}</p></div><div class="amount"><button data-quantity="${esc(r.key)}" class="outline" title="Einkaufsmenge ändern">${+r.need.toFixed(1)} ${esc(r.unit)}</button><small>${r.packs===null?'Packung / Preis ungeklärt':`${r.packs} × ${r.pack} ${r.unit} · ${euro(r.cost)}`}</small><button class="tiny" data-price="${r.food}">Preis bearbeiten</button></div></div>`).join('')}`).join(''):'<div class="empty-card"><span>Deine Einkaufsliste wartet auf den ersten Plan.</span></div>'}${state.manual.length?`<h3 class="group-title">Meine Ergänzungen</h3>${state.manual.map(r=>`<div class="list-row"><input type="checkbox" data-manual-check="${r.id}" ${r.checked?'checked':''} aria-label="${esc(r.name)} gekauft"><div class="grow ${r.checked?'muted':''}">${esc(r.name)}<p>${esc(r.amount)}</p></div><button class="icon-btn" data-manual-delete="${r.id}" aria-label="Artikel entfernen">×</button></div>`).join('')}`:''}</div>`);$('#print').onclick=()=>window.print();$('#export-list').onclick=()=>download('einkaufsliste.txt',`Tisch & Tag · ${weekLabel()}\n\n`+list.map(r=>`${state.checked[state.week+'|'+r.key]?'[x]':'[ ]'} ${r.name}: ${r.need} ${r.unit} · ${r.packs??'?'} Packungen · ${euro(r.cost)}`).join('\n')+'\n'+state.manual.map(r=>`${r.checked?'[x]':'[ ]'} ${r.name} ${r.amount}`).join('\n')+`\n\nGeschätzte Summe: ${euro(t.buy)}${t.unknown?' (unvollständig)':''}`,'text/plain');$('#manual-add').onclick=()=>{modal('Artikel ergänzen','<form id="manual-form"><label>Artikel<input name="name" required></label><label style="margin-top:14px">Menge / Hinweis<input name="amount" placeholder="z. B. 1 Packung"></label><div class="form-actions"><button class="primary">Ergänzen</button></div></form>');$('#manual-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.manual.push({id:uid(),name:f.get('name'),amount:f.get('amount'),checked:false});save();$('#dialog').close();render();};};document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{state.checked[state.week+'|'+b.dataset.check]=b.checked;save();render();});document.querySelectorAll('[data-manual-check]').forEach(b=>b.onchange=()=>{state.manual.find(x=>x.id===b.dataset.manualCheck).checked=b.checked;save();});document.querySelectorAll('[data-manual-delete]').forEach(b=>b.onclick=()=>{state.manual=state.manual.filter(x=>x.id!==b.dataset.manualDelete);save();render();});document.querySelectorAll('[data-quantity]').forEach(b=>b.onclick=()=>{const r=list.find(x=>x.key===b.dataset.quantity);modal('Einkaufsmenge anpassen',`<form id="quantity-form"><label>${esc(r.name)} in ${esc(r.unit)}<input name="qty" type="number" min="0" step="0.1" value="${r.need}" required></label><p class="source-note">Manuelle Mengen bleiben beim Umplanen erhalten. Mit „Zurücksetzen“ wird wieder aus dem Plan berechnet.</p><div class="form-actions"><button type="button" class="secondary" id="reset-qty">Zurücksetzen</button><button class="primary">Speichern</button></div></form>`);$('#quantity-form').onsubmit=e=>{e.preventDefault();state.overrides[state.week+'|'+r.key]=+new FormData(e.target).get('qty');save();$('#dialog').close();render();};$('#reset-qty').onclick=()=>{delete state.overrides[state.week+'|'+r.key];save();$('#dialog').close();render();};});document.querySelectorAll('[data-price]').forEach(b=>b.onclick=()=>editPrice(b.dataset.price));}
function editPrice(id){const f=foods[id];if(!f){toast('Packungsdaten eigener Zutaten noch nicht im Katalog konfiguriert.');return;}modal('Packungspreis bearbeiten',`<form id="price-form"><p>${esc(f.name)} · ${f.pack} ${f.unit} pro Packung</p><label>Preis in Euro<input name="price" type="number" min="0" step="0.01" required value="${state.prices[id]??f.price}"></label><p class="source-note">Quelle: ${state.priceDates[id]?'Manuell · '+state.priceDates[id]:'Beispielpreis · 04.11.2026'}. Neue Preise werden als manuelle Angabe mit heutigem Datum gespeichert.</p><div class="form-actions"><button class="primary">Preis speichern</button></div></form>`);$('#price-form').onsubmit=e=>{e.preventDefault();state.prices[id]=+new FormData(e.target).get('price');state.priceDates[id]=new Date().toLocaleDateString('de-DE');save();$('#dialog').close();render();};}
function renderPantry(){shell(heading('SCHON DA? PERFEKT.','Dein kleiner Vorrat.','Vorhandene Zutaten werden von deiner Einkaufsliste abgezogen.',`<button class="primary" id="add-pantry">＋ Vorrat ergänzen</button>`)+`<div class="section"><div class="success">Eine Planung verändert deine Vorräte nicht. Erst „Gekocht“ im Mahlzeitenmenü zieht die verwendeten Mengen ab.</div>${Object.entries(state.pantry).filter(([,q])=>q>0).length?Object.entries(state.pantry).filter(([,q])=>q>0).map(([id,q])=>`<div class="list-row"><span style="font-size:25px">♧</span><div class="grow"><b>${esc(foods[id]?.name||id)}</b><p>${esc(foods[id]?.group||'Eigene Zutaten')}</p></div><span>${+q.toFixed(1)} ${esc(foods[id]?.unit||'')}</span><button class="secondary" data-pantry="${esc(id)}">Bearbeiten</button></div>`).join(''):'<div class="empty-card" style="margin-top:20px"><span style="font-size:30px">♧</span><span>Noch keine Vorräte erfasst.<br>Beginne mit Reis, Haferflocken oder Olivenöl.</span></div>'}</div>`);$('#add-pantry').onclick=()=>editPantry();document.querySelectorAll('[data-pantry]').forEach(b=>b.onclick=()=>editPantry(b.dataset.pantry));}
function editPantry(id='reis'){modal('Vorrat erfassen',`<form id="pantry-form"><label>Zutat<select name="food">${Object.entries(foods).map(([k,f])=>`<option value="${k}" ${id===k?'selected':''}>${esc(f.name)} (${f.unit})</option>`).join('')}</select></label><label style="margin-top:16px">Vorhandene Menge (in der Einheit oben)<input name="qty" type="number" min="0" step="0.1" required value="${state.pantry[id]||0}"></label><div class="form-actions"><button class="primary">Vorrat speichern</button></div></form>`);$('#pantry-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.pantry[f.get('food')]=+f.get('qty');save();$('#dialog').close();render();};}
function renderSettings(){const s=state.settings;const checkset=(name,items,selected)=>items.map((v,i)=>`<label class="check"><input type="checkbox" name="${name}" value="${typeof v==='object'?v.value:v}" ${selected.includes(typeof v==='object'?v.value:v)?'checked':''}>${esc(typeof v==='object'?v.label:v)}</label>`).join('');shell(heading('PASST ZU DIR. PASST IN DEINEN ALLTAG.','So isst du am liebsten.','Deine Regeln gelten für die Planung. Allergenausschlüsse haben immer Vorrang.')+`<form id="settings-form"><section class="section"><h2>Deine Woche</h2><div class="form-grid"><label>Woche (beliebiges Datum in der gewünschten Woche)<input name="week" type="date" required value="${state.week}"></label><label>Personen / Standardportionen<input name="persons" type="number" min="1" max="30" value="${s.persons}" required></label><label>Einkaufsbudget in Euro<input name="budget" type="number" min="1" step="0.01" value="${s.budget}" required></label><label>Maximale Gesamtzeit pro Rezept in Minuten<input name="maxTime" type="number" min="5" max="600" value="${s.maxTime}" required></label></div><h3 style="margin-top:23px">An diesen Tagen</h3><div class="checks">${checkset('days',days.map((d,i)=>({label:d,value:i})),s.days)}</div><h3 style="margin-top:23px">Diese Mahlzeiten</h3><div class="checks">${checkset('meals',meals,s.meals)}</div><p class="source-note">${s.persons} Personen · ${s.days.length*s.meals.length} mögliche Mahlzeiten · Budget gilt für die ausgewählte Woche. Portionen sind je Mahlzeit anpassbar. Nicht ausgewählte Tage und Mahlzeiten bleiben ungeplant.</p></section><section class="section"><h2>Ernährungsform & persönliche Wünsche</h2><div class="form-grid"><label>Ernährungsform<select name="diet">${['Mischkost','Vegetarisch','Vegan','Pescetarisch','Flexitarisch'].map(d=>`<option ${s.diet===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Ungemochte Zutaten / persönliche Ausschlüsse<input name="excludes" value="${esc(s.excludes)}" placeholder="z. B. Pilze, Sellerie"></label></div><h3 style="margin-top:23px">Kombinierbare Ziele</h3><div class="checks">${checkset('goals',['Kalorienarm','Kalorienreich','Proteinreich','Low Carb','Ausgewogen'],s.goals)}</div><div class="form-grid" style="margin-top:20px"><label>Proteinreich: mindestens g Protein pro Portion<input name="minProtein" type="number" min="0" value="${s.minProtein}" required></label><label>Low Carb: höchstens g Kohlenhydrate pro Portion<input name="maxCarbs" type="number" min="0" value="${s.maxCarbs}" required></label><label>Kalorienarm: höchstens kcal pro Portion<input name="maxKcal" type="number" min="1" value="${s.maxKcal}" required></label><label>Kalorienreich: mindestens kcal pro Portion<input name="minKcal" type="number" min="1" value="${s.minKcal}" required></label></div><p class="source-note">Die Grenzen gelten verbindlich pro Rezeptportion bei aktivem Ziel. „Ausgewogen“ ist eine Präferenz ohne zusätzliche Zahlenregel. Geplante Nährwerte stellen keine vollständige Tagesernährung dar. Flexitarisch lässt alle Ernährungsformen zu.</p><label class="check"><input type="checkbox" name="preferFav" ${s.preferFav?'checked':''}>Favoriten bei automatischer Planung bevorzugen</label></section><section class="section"><h2>Allergene & Unverträglichkeiten</h2><p class="muted" style="line-height:1.7">Mehrfachauswahl möglich. Rezepte mit ungeklärten Zutaten werden bei aktiven Ausschlüssen nicht automatisch eingeplant.</p><div class="checks">${checkset('allergens',allergens,s.allergens)}</div><div class="checks" style="margin-top:20px"><label class="check"><input type="checkbox" name="glutenfree" ${s.glutenfree?'checked':''}>Glutenfreie Ernährung</label><label class="check"><input type="checkbox" name="lactosefree" ${s.lactosefree?'checked':''}>Laktosefreie Ernährung</label></div><div class="warning">Milchallergie und Laktoseintoleranz sind unterschiedliche Bedingungen. Der aktuelle Katalog schließt bei laktosefreier Planung vorsorglich alle Milchzutaten aus. Getreide- und Nussarten werden derzeit jeweils als Gruppe ausgeschlossen. Produktetiketten einschließlich Spurenhinweisen immer prüfen.</div></section><div id="settings-errors" role="alert"></div><div class="form-actions"><button class="primary" type="submit">Einstellungen speichern</button></div></form><section class="section" style="margin-top:28px"><h2>Deine Daten & Verbindungen</h2><p class="muted">Daten bleiben in diesem Browser. Für ein anderes Gerät exportieren und dort wiederherstellen.</p><div class="row" style="flex-wrap:wrap"><button class="secondary" id="export-data">↓ Alle Daten exportieren</button><button class="secondary" id="restore-data">Daten wiederherstellen</button><button class="secondary" id="delete-data">Persönliche Daten löschen</button></div><label style="margin-top:22px">Optionaler Importserver (HTTPS-Adresse, z. B. https://import.example.com/api/import)<input id="endpoint" type="url" value="${esc(localStorage.getItem('tisch-import-endpoint')||'')}" placeholder="Nicht eingerichtet"></label><button class="secondary" id="save-endpoint" style="margin-top:12px">Verbindung speichern</button><p class="source-note">Kein externer KI-Dienst eingerichtet. Textimport funktioniert ohne Server. Keine API-Schlüssel in dieses Feld eintragen.</p></section>`);
$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const next={...s};for(const k of ['persons','budget','maxTime','minProtein','maxCarbs','maxKcal','minKcal'])next[k]=+f.get(k);for(const k of ['diet','excludes'])next[k]=f.get(k);for(const k of ['allergens','goals','meals'])next[k]=f.getAll(k);next.days=f.getAll('days').map(Number);for(const k of ['glutenfree','lactosefree','preferFav'])next[k]=f.has(k);if(!next.days.length||!next.meals.length){$('#settings-errors').innerHTML='<div class="warning">Bitte mindestens einen Tag und eine Mahlzeit auswählen.</div>';return;}if(next.goals.includes('Kalorienarm')&&next.goals.includes('Kalorienreich')&&next.minKcal>next.maxKcal){$('#settings-errors').innerHTML='<div class="warning">Kalorienarm und kalorienreich widersprechen sich mit diesen Grenzen. Bitte Grenzen oder Ziele anpassen.</div>';return;}const nextWeek=monday(f.get('week'));const removed=Object.entries(state.plans[nextWeek]||{}).filter(([k,p])=>!next.days.includes(+k.split('-')[0])||!next.meals.includes(k.split('-')[1])||!eligible(recipe(p.recipe),next,k.split('-')[1]));if(removed.length){modal('Plan an neue Regeln anpassen',`<p>${removed.length} Mahlzeiten passen nicht mehr zu den gewählten Tagen oder Regeln. Diese Mahlzeiten und ihre verknüpften Reste werden nach Bestätigung aus der ausgewählten Woche entfernt.</p><div class="form-actions"><button class="secondary" id="cancel-settings">Abbrechen</button><button class="primary" id="confirm-settings">Anpassen & speichern</button></div>`);$('#cancel-settings').onclick=()=>$('#dialog').close();$('#confirm-settings').onclick=()=>{const pl=state.plans[nextWeek]||{};const keys=new Set(removed.map(([k])=>k));for(const[k,p]of Object.entries(pl))if(keys.has(p.leftover))keys.add(k);for(const k of keys){const p=pl[k];if(p?.leftover&&pl[p.leftover]&&!keys.has(p.leftover)&&!pl[p.leftover].cooked)pl[p.leftover].portions-=p.portions;delete pl[k];}state.settings=next;state.week=nextWeek;save();$('#dialog').close();render();toast('Einstellungen und ausgewählter Plan aktualisiert.');};return;}state.settings=next;state.week=nextWeek;state.plans[nextWeek]??={};save();toast('Einstellungen gespeichert.');render();};$('#export-data').onclick=()=>download('tisch-und-tag-daten.json',JSON.stringify(state,null,2));$('#restore-data').onclick=()=>{modal('Daten wiederherstellen','<p>Eine zuvor exportierte Sicherung ersetzt die aktuellen Daten.</p><label>Sicherungsdatei<input type="file" id="restore-file" accept="application/json"></label><div class="form-actions"><button class="primary" id="confirm-restore">Sicherung laden</button></div>');$('#confirm-restore').onclick=async()=>{try{const file=$('#restore-file').files[0];if(!file)throw Error('Bitte Datei auswählen.');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.recipes)||!data.settings||!data.plans||!data.pantry||!data.prices||!data.checked||!data.manual||!data.overrides||data.recipes.some(r=>!Array.isArray(r.ingredients)||!Array.isArray(r.steps)||!r.id||!r.meal))throw Error('Ungültige Sicherungsdatei.');state=data;save();$('#dialog').close();render();toast('Sicherung wiederhergestellt.');}catch(e){toast(e.message);}};};$('#delete-data').onclick=()=>{modal('Alle persönlichen Daten löschen?', '<p>Rezepte, Pläne, Vorräte und Einstellungen werden auf diesem Gerät gelöscht. Exportiere bei Bedarf vorher eine Sicherung.</p><div class="form-actions"><button class="secondary" id="cancel-clear">Abbrechen</button><button class="primary" id="confirm-clear">Jetzt löschen</button></div>');$('#cancel-clear').onclick=()=>$('#dialog').close();$('#confirm-clear').onclick=()=>{localStorage.removeItem('tisch-tag-v1');localStorage.removeItem('tisch-import-endpoint');state=defaultState();state.plans[state.week]={};save();$('#dialog').close();render();toast('Persönliche Daten gelöscht.');};};$('#save-endpoint').onclick=()=>{const v=$('#endpoint').value;if(v&&!safeUrl(v)){toast('Bitte eine öffentliche HTTPS-Adresse eingeben.');return;}localStorage.setItem('tisch-import-endpoint',v);toast(v?'Importserver gespeichert.':'Importserver entfernt.');};}
function renderQuick(){
 const q=state.quick||{budget:5,portions:1,maxTime:30,meal:'Mittagessen',highProtein:false,minProtein:25,usePantry:true};
 const result=quickSuggestions(state,q);const shown=result.matches.length?result.matches:result.alternatives;
 shell(heading('SPONTAN HUNGER? SCHNELL EINE IDEE.','Ein Essen. Dein Budget.','Für heute Mittag oder zwischendurch – unabhängig von deinem Wochenplan.')+`<section class="section"><form id="quick-form"><div class="form-grid"><label>Budget für das gesamte Essen in Euro<input name="budget" type="number" min="0" max="10000" step="0.01" required value="${q.budget}"></label><label>Portionen<input name="portions" type="number" min="1" max="30" step="1" required value="${q.portions}"></label><label>Maximale Gesamtzeit in Minuten<input name="maxTime" type="number" min="1" max="600" step="1" required value="${q.maxTime}"></label><label>Mahlzeit<select name="meal">${meals.map(m=>`<option ${q.meal===m?'selected':''}>${m}</option>`).join('')}</select></label></div><div class="chips" style="margin-top:16px">${[3,5,10].map(n=>`<button type="button" class="chip ${q.budget===n?'green':''}" data-quick-budget="${n}">${n} €</button>`).join('')}<span class="tiny muted" style="align-self:center">Budget schnell wählen</span></div><div class="form-grid" style="margin-top:20px"><div><label class="check"><input name="highProtein" type="checkbox" ${q.highProtein?'checked':''}>Proteinreich / High Protein</label><label class="check"><input name="usePantry" type="checkbox" ${q.usePantry?'checked':''}>Meine vorhandenen Vorräte berücksichtigen</label></div><label>Proteinreich: mindestens g Protein pro Portion<input name="minProtein" type="number" min="0" max="200" step="1" required value="${q.minProtein}"></label></div><p class="source-note">Budget = geschätzte neue Einkäufe für alle Portionen, einschließlich ganzer Packungen. Ernährungsform, Allergenausschlüsse und aktive Ernährungsziele aus deinen Einstellungen gelten weiter. Nährwerte sind Schätzungen pro Portion.</p><div class="form-actions"><button class="primary" type="submit">✧ Passendes Gericht finden</button></div></form></section><div aria-live="polite"><div class="week-toolbar"><h2 style="margin:0">${result.matches.length?`${result.matches.length} passende ${result.matches.length===1?'Idee':'Ideen'}`:'Kein Gericht innerhalb deines Budgets'}</h2><span class="badge">${euro(q.budget)} · ${q.portions} ${q.portions===1?'Portion':'Portionen'} · bis ${q.maxTime} Min.</span></div>${!result.matches.length?`<div class="warning">${result.alternatives.length?`Mit den aktuellen Regeln kostet die günstigste passende Option ${euro(result.alternatives[0].buy)} an neuen Einkaufspackungen. Du kannst unten die teureren Alternativen prüfen, Vorräte ergänzen oder dein Budget bewusst erhöhen.`:'Für diese Kombination gibt es in deiner Sammlung kein passendes Rezept mit vollständigen Preisen. Versuche mehr Zeit, andere freiwillige Ziele oder ergänze ein passendes Rezept. Allergenausschlüsse bleiben verbindlich.'}</div>`:''}<div class="recipe-grid quick-results">${shown.map(x=>`<div>${card(x.recipe)}<div class="quick-cost"><div class="row" style="justify-content:space-between"><b>${euro(x.buy)} Einkauf</b><span class="badge">${x.recipe.protein??'?'} g Protein / Portion</span></div><p>${euro(x.used)} Zutatenwert für ${q.portions} ${q.portions===1?'Portion':'Portionen'}${x.buy>q.budget?` · <span class="error">${euro(x.buy-q.budget)} über Budget</span>`:''}</p><button class="secondary" data-quick-list="${x.recipe.id}">Einkauf für dieses Essen ansehen</button></div></div>`).join('')}</div></div>`);
 $('#quick-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.quick={budget:+f.get('budget'),portions:+f.get('portions'),maxTime:+f.get('maxTime'),meal:f.get('meal'),highProtein:f.has('highProtein'),minProtein:+f.get('minProtein'),usePantry:f.has('usePantry')};save();renderQuick();};
 document.querySelectorAll('[data-quick-budget]').forEach(b=>b.onclick=()=>{$('#quick-form [name=budget]').value=b.dataset.quickBudget;$('#quick-form').requestSubmit();});bindCards();
 // Quick results open scaled to the requested portions, without altering the weekly plan.
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecipe(b.dataset.open,q.portions));
 document.querySelectorAll('[data-quick-list]').forEach(b=>b.onclick=()=>{const x=shown.find(x=>x.recipe.id===b.dataset.quickList);modal('Einkauf für dein spontanes Essen',`<h3>${esc(x.recipe.title)} · ${q.portions} ${q.portions===1?'Portion':'Portionen'}</h3><div class="success">${euro(x.buy)} neue Einkaufspackungen · ${euro(x.used)} anteiliger Zutatenwert</div>${x.rows.map(r=>`<label class="list-row"><input type="checkbox"><span class="grow">${esc(r.name)}<span class="source-note" style="display:block;margin:4px 0">Benötigt: ${+r.qty.toFixed(1)} ${esc(r.unit)} · noch kaufen: ${+r.need.toFixed(1)} ${esc(r.unit)}</span></span><span>${r.packs} × ${r.pack} ${esc(r.unit)}<span class="source-note" style="display:block">${euro(r.cost)}</span></span></label>`).join('')}<p class="source-note">Diese separate Liste verändert weder Wochenplan noch Vorräte. Beispielpreise beziehungsweise deine manuell korrigierten Preise.</p><div class="form-actions"><button class="primary" id="export-quick">Als Text speichern / teilen</button></div>`);$('#export-quick').onclick=()=>download('schnelles-essen-einkauf.txt',`${x.recipe.title} · ${q.portions} Portionen\n\n`+x.rows.map(r=>`${r.name}: ${+r.need.toFixed(1)} ${r.unit} noch kaufen · ${r.packs} × ${r.pack} ${r.unit} · ${euro(r.cost)}`).join('\n')+`\n\nGeschätzter Einkauf: ${euro(x.buy)}\nPreise sind Beispiele oder manuelle Angaben.`,'text/plain');});
}

function render(){({quick:renderQuick,plan:renderPlan,recipes:renderRecipes,shop:renderShop,pantry:renderPantry,settings:renderSettings})[page]();}render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
